/* RemCard — страница «Релизы»: что из прототипа уже есть на remcard.ru (релиз 1, новый дизайн),
   что добавляем (релиз 2), и как внедрять блоками, не ломая работающий сайт. */
(function () {
  const { route, icon, esc, R, rel2 } = window.RC;

  // Блок = раздел сайта, который можно заменить отдельно. url — адреса на действующем remcard.ru.
  const R1 = [
    ['award', 'Сертификат', 'новый дизайн: Карта, Купон, Лист · QR · список партнёров', '/certificate/[code]'],
    ['home', 'Главная', 'один вход: быстрый расчёт → калькулятор', '/'],
    ['calculator', 'Калькулятор ремонта', '6 типов объектов, уровни, стиль, опции, смета по этапам', '/estimate'],
    ['ruler', 'Калькуляторы материалов', '20 расчётов количества и стоимости', '/calculators'],
    ['route', 'Навигатор', '12 этапов · 69 подэтапов · 500 задач · таймеры · приёмка — данные без изменений', '/navigator'],
    ['store', 'Каталог', 'товары, услуги, мастера, компании, магазины · разделы · этапы · поиск', '/catalog'],
    ['phone', 'Консьерж', 'заявка на ремонт под присмотром', '/concierge · /request'],
    ['user', 'Кабинет клиента', 'вход · покупки и обращения · карта и баллы · сертификаты · отзывы · избранное · уведомления · профиль', '/client/*'],
    ['moon', 'День и ночь', 'обе темы во всех разделах', ''],
  ];
  const R2 = [
    ['heart', 'Забота RemCard', 'закупка за вас, доставка, хранение, страхование · исполнители регистрируются в PROF'],
    ['badge-percent', 'Рассрочка и кредит', 'карточка товара, список покупок, смета'],
    ['waves', 'Калькуляторы объектов под ключ', 'бассейн, навес, мангал, автополив… · 11 расчётов · ценовые сегменты'],
    ['trees', 'Участок и двор', 'тип объекта, этап «Благоустройство», разделы каталога «Строительство» и «Участок и двор»'],
    ['sliders-horizontal', 'Каталог глубже', 'наборы «под задачу», фильтры по атрибутам товара, карта районов, срезы по помещению и стилю'],
    ['shopping-bag', 'Консьерж: купить за меня', 'заявка без ремонта — найти лучшее предложение'],
    ['package', 'Партнёрам: закупки', 'поиск поставщиков, прайсы B2B, сервисы для сделок — в кабинете PROF'],
  ];

  const li = ([ic, t, d, url]) => `<li>${icon(ic)}<div><b>${esc(t)}</b>${url ? ` <span class="xs muted">${esc(url)}</span>` : ''}<small>${esc(d)}</small></div></li>`;

  // Порядок сборки: сначала общий фундамент, затем блоки по готовности — каждый встаёт на свой адрес.
  const PUZZLE = [
    ['0', 'Дизайн-система', 'цвета, шрифт, отступы, шапка и подвал, тема, кнопки, карточки, чипы. Функции не меняет', true],
    ['1', 'Сертификат', 'ни от чего не зависит — первым'],
    ['2', 'Главная', 'ведёт в старые разделы, пока их не заменили'],
    ['3', 'Калькуляторы', 'расчёт и материалы — те же формулы'],
    ['4', 'Каталог', 'те же товары, услуги и партнёры из PROF'],
    ['5', 'Навигатор', 'те же таблицы этапов и задач'],
    ['6', 'Консьерж', 'та же заявка'],
    ['7', 'Кабинет', 'раздел за разделом: карта, покупки, отзывы…'],
  ];

  function page() {
    return `<section class="section--tight"><div class="wrap">
      <div class="crumbs"><a href="#/">Главная</a>${icon('chevron-right')}<span>Релизы</span></div>
      <div class="section-head" style="align-items:flex-start;margin-top:.75rem"><div><span class="eyebrow eyebrow--red">План реализации</span><h1 style="margin:.4rem 0 .3rem">Два релиза</h1>
        <p class="lead">Релиз 1 — всё, что уже есть на remcard.ru, в новом дизайне. Релиз 2 — новые функции.</p></div>
        <div class="relsw" role="group" aria-label="Объём релиза">${[1, 2].map((n) => `<button type="button" class="${R(n) && !R(n + 1) ? 'is-on' : ''}" data-release="${n}">Релиз ${n}</button>`).join('')}</div></div>
      <p class="xs muted" style="margin:-.25rem 0 1.25rem">Переключатель в шапке показывает сайт в объёме выбранного релиза. Релиз 2 включает релиз 1.</p>

      <div class="rel">
        <div class="card card--pad-lg"><h3>Релиз 1 <span class="pill pill--green">есть на сайте</span></h3><p class="small muted" style="margin-top:.25rem">Те же данные и адреса. Меняется только экран.</p><ul>${R1.map(li).join('')}</ul></div>
        <div class="card card--pad-lg"><h3>Релиз 2 ${rel2('новое')}</h3><p class="small muted" style="margin-top:.25rem">Новые данные и роли партнёров. Делаем после приёмки релиза 1.</p><ul>${R2.map(li).join('')}</ul></div>
      </div>
    </div></section>

    <section class="section"><div class="wrap">
      <div class="section-head"><div><h2>Как собирать</h2><p class="muted" style="margin-top:.3rem">Каждый блок встаёт на свой адрес, когда готов. Остальной сайт работает как раньше.</p></div></div>
      <div class="puzzle">${PUZZLE.map(([n, t, d, base]) => `<div class="pz ${base ? 'is-base' : ''}"><span class="pz__n">${base ? 'Фундамент' : 'Блок ' + n}</span><b>${esc(t)}</b><small>${esc(d)}</small></div>`).join('')}</div>
      <div class="rules" style="margin-top:1rem">
        <div class="card"><b>Один адрес — одна замена</b><p>Новый экран встаёт на тот же URL. Старые ссылки, QR и SEO не ломаются.</p></div>
        <div class="card"><b>Данные не трогаем</b><p>Релиз 1 читает те же таблицы и API. Новые поля и роли — только в релизе 2.</p></div>
        <div class="card"><b>Флаг на блок</b><p>Раздел включается отдельно: проверили на тесте в двух темах и на телефоне — включили всем. Откат за минуту.</p></div>
      </div>
      <div class="card card--pad-lg" style="margin-top:1rem"><b>Цикл одного блока</b><div class="row" style="gap:.5rem;flex-wrap:wrap;margin-top:.6rem">${['Утверждаем экран в прототипе', 'Задание на блок', 'Тестовая сборка', 'Проверка: две темы, телефон, старые ссылки', 'Включаем флаг'].map((x, i) => `<span class="chip">${i + 1}. ${x}</span>`).join('')}</div></div>
    </div></section>`;
  }

  route('/releases', page);
})();
